#!/bin/bash
# tools/pi/sk-audio.sh — set the kiosk's default speaker and microphone by NAME at kiosk start.
# Run by ~/.local/bin/sk-kiosk.sh (generated by tools/pi/pi-setup.sh) in the background before
# Chromium starts; also safe to run by hand:   bash tools/pi/sk-audio.sh
#
# PipeWire IDs (the numbers in `wpctl status`) change on every replug/boot, so the devices are
# found by a part of their name. Hardware notes (tools/pi/README.md): the speaker shares power
# with the LCDs, so above 0.8 the LCDs brown out — the volume is clamped to MAX_VOLUME.
#
# Change the names/volume here, or (so a `git pull` does not undo it) in ~/.config/sk-audio.conf,
# which is sourced after these defaults and may set any of the four variables below.
# Settings -> System -> Speaker volume writes SINK_VOLUME there too (/usr/local/bin/sk-volume, pi-setup.sh
# step 10), and php/api/system_power.php reads MAX_VOLUME from this file: keep it on its own line.

SINK_NAME="CD002-AUDIO"                 # speaker: part of the name under Audio -> Sinks
SOURCE_NAME="AB13X Headset Adapter"     # microphone: part of the name under Audio -> Sources
SINK_VOLUME="0.75"                      # 0.0 .. MAX_VOLUME
MAX_VOLUME="0.8"                        # never above this: the LCDs brown out (shared power)

WAIT_S=30                               # PipeWire / USB devices may appear a few seconds after login

CONF="$HOME/.config/sk-audio.conf"
# shellcheck source=/dev/null
[ -f "$CONF" ] && . "$CONF"

log() { echo "[sk-audio $(date '+%H:%M:%S')] $*"; }

command -v wpctl >/dev/null 2>&1 || { log "wpctl not found (no PipeWire/WirePlumber): nothing done"; exit 0; }
export XDG_RUNTIME_DIR="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"

# find_id SECTION NAME -> the node id of the first line under "Audio -> SECTION" containing NAME.
# `wpctl status` lists, e.g.:
#   Audio
#    ├─ Sinks:
#    │  *   46. Built-in Audio Stereo        [vol: 0.40]
#    │      52. CD002-AUDIO Analog Stereo    [vol: 1.00]
#    ├─ Sink endpoints:
# A section ends at the next header line (a line ending in ':'); only the Audio block is read
# (Video has its own Sinks/Sources).
find_id() {
  wpctl status 2>/dev/null | awk -v sec="$1:" -v want="$2" '
    /^Audio/ { audio = 1; next }
    /^(Video|Settings)/ { audio = 0 }
    !audio { next }
    /:[[:space:]]*$/ { insec = (index($0, sec) > 0); next }
    insec && index($0, want) {
      if (match($0, /[0-9]+\./)) { print substr($0, RSTART, RLENGTH - 1); exit }
    }'
}

# Clamp the volume to MAX_VOLUME (awk: bash has no floats).
VOL="$(awk -v v="$SINK_VOLUME" -v m="$MAX_VOLUME" 'BEGIN { v += 0; m += 0; if (v > m) v = m; if (v < 0) v = 0; printf "%.2f", v }')"
[ "$VOL" != "$(awk -v v="$SINK_VOLUME" 'BEGIN { printf "%.2f", v + 0 }')" ] && log "volume $SINK_VOLUME clamped to $VOL (MAX_VOLUME $MAX_VOLUME)"

SINK_ID=""
SOURCE_ID=""
for _ in $(seq "$WAIT_S"); do
  [ -z "$SINK_ID" ] && SINK_ID="$(find_id Sinks "$SINK_NAME")"
  [ -z "$SOURCE_ID" ] && SOURCE_ID="$(find_id Sources "$SOURCE_NAME")"
  [ -n "$SINK_ID" ] && [ -n "$SOURCE_ID" ] && break
  sleep 1
done

if [ -n "$SINK_ID" ]; then
  wpctl set-default "$SINK_ID" && wpctl set-mute "$SINK_ID" 0 && wpctl set-volume "$SINK_ID" "$VOL" \
    && log "speaker '$SINK_NAME' = id $SINK_ID: default, volume $VOL"
else
  log "speaker '$SINK_NAME' not found under Audio -> Sinks (plugged into the Pi's own USB port?)"
fi
if [ -n "$SOURCE_ID" ]; then
  wpctl set-default "$SOURCE_ID" && log "microphone '$SOURCE_NAME' = id $SOURCE_ID: default"
else
  log "microphone '$SOURCE_NAME' not found under Audio -> Sources"
fi
exit 0
